#include <iostream>
using namespace std;

void bubbleSort(int arr[], int size)
{
    for (int i = 0; i < size - 1; i++)
    {
        for (int j = 0; j < size - i - 1; j++)
        {
            if (arr[j] > arr[j + 1])
            {
                swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main()
{
    int arr[] = {64, 34, 25, 12, 22, 11};
    int size = sizeof(arr) / sizeof(arr[0]);

    cout << "Unsorted array:" << endl;
    for (int i = 0; i < size; i++)
    {
        cout << arr[i] << " ";
    }
    cout << endl;

    bubbleSort(arr, size);

    cout << "Sorted array:" << endl;
    for (int i = 0; i < size; i++)
    {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```

**Explanation:**

* **Bubble Sort** is a simple sorting algorithm that repeatedly compares adjacent elements and swaps them if they are out of order.
* The algorithm has two nested loops, iterating over the array.
* In the outer loop, we track the number of swaps made in the inner loop.
* In the inner loop, we compare the current elements and swap them if they are out of order.
* The algorithm continues until no swaps are made in the inner loop, indicating that the array is now sorted.

**Output:**

