```javascript
class Node {
  constructor(data) {
    this.data = data;
    this.next = null;
    this.prev = null;
  }
}

class DoubleLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
  }

  isEmpty() {
    return this.head === null;
  }

  append(data) {
    const newNode = new Node(data);

    if (this.isEmpty()) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      this.tail.next = newNode;
      newNode.prev = this.tail;
      this.tail = newNode;
    }
  }

  prepend(data) {
    const newNode = new Node(data);

    if (this.isEmpty()) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      newNode.next = this.head;
      newNode.prev = null;
      this.head.prev = newNode;
      this.head = newNode;
    }
  }

  remove(data) {
    let current = this.head;

    while (current !== null && current.data !== data) {
      current = current.next;
    }

    if (current === null) {
      return;
    }

    if (current === this.head) {
      this.head = current.next;
    } else {
      current.prev.next = current.next;
      if (current.next !== null) {
        current.next.prev = current.prev;
      }
    }

    current.next = null;
    current.prev = null;
  }

  search(data) {
    let current = this.head;

    while (current !== null && current.data !== data) {
      current = current.next;
    }

    return current !== null;
  }
}
```

**Explanation:**

* **Node** class: Represents a single node in the list, with data and pointers to the next and previous nodes.
* **DoubleLinkedList** class: Implements a doubly linked list data structure with head and tail pointers.
* **append()** method: Inserts a new node at the end of the list.
* **prepend()** method: Inserts a new node at the beginning of the list.
* **remove()** method: Removes a node from the list.
* **search()** method: Checks if a node with the given data exists in the list.

